describe('checkDatabase', () => {
  it('returns true for a healthy database', () => {
    const db = createDatabase();
    expect(checkDatabase(db)).toBe(true);
  });
});

export function checkDatabase(db: DatabaseSync): boolean {
  try {
    db.exec('SELECT 1');
    return true;
  } catch {
    return false;
  }
}

